from django.urls import path
from django.contrib.auth import views as auth
from studio import views as v
urlpatterns=[path('documentos/<uuid:ident>/corrigir/',v.edit_content,name='edit_content')]
urlpatterns += [path('',v.home,name='home'),path('conta/cadastrar/',v.signup,name='signup'),path('conta/confirmar/<uid>/<token>/',v.activate,name='activate'),path('conta/entrar/',v.LoginView.as_view(),name='login'),path('conta/sair/',auth.LogoutView.as_view(),name='logout'),path('conta/recuperar/',auth.PasswordResetView.as_view(template_name='form.html',email_template_name='registration/password_reset_email.txt',extra_context={'title':'Recuperar senha','button':'Enviar link'}),name='password_reset'),path('conta/recuperar/enviado/',auth.PasswordResetDoneView.as_view(template_name='notice.html',extra_context={'title':'Confira seu e-mail','text':'Se houver uma conta ativa, você receberá um link.'}),name='password_reset_done'),path('conta/redefinir/<uidb64>/<token>/',auth.PasswordResetConfirmView.as_view(template_name='form.html',extra_context={'title':'Redefinir senha','button':'Salvar senha'}),name='password_reset_confirm'),path('conta/redefinida/',auth.PasswordResetCompleteView.as_view(template_name='notice.html',extra_context={'title':'Senha atualizada','text':'Você já pode entrar.'}),name='password_reset_complete'),path('conta/chave/',v.key_settings,name='keys'),path('conta/chave/excluir/',v.delete_key,name='delete_key'),path('documentos/',v.documents,name='documents'),path('documentos/enviar/',v.upload,name='upload'),path('documentos/<uuid:ident>/',v.detail,name='detail'),path('documentos/<uuid:ident>/preparar/',v.prepare,name='prepare'),path('documentos/<uuid:ident>/iniciar/',v.start,name='start'),path('documentos/<uuid:ident>/status/',v.status,name='status'),path('documentos/<uuid:ident>/cancelar/',v.cancel,name='cancel'),path('documentos/<uuid:ident>/aprovar/',v.approve,name='approve'),path('documentos/<uuid:ident>/video/',v.attach_video,name='attach_video'),path('documentos/<uuid:ident>/download/<int:index>/',v.download,name='download'),path('documentos/<uuid:ident>/excluir/',v.delete_document,name='delete_document')]
